) AS (
  VALUES 
    (321::BIGINT, 'El profe es buena nota y todo, las clases son mas trabajar que explicar, explica 30 minutos en una clase de 4 horas. Proyectos largos por varias semanas y mucho trabajo en clase todos los días. Honestamente vale la pena debido a que su actual asistente es muy buena, no como el anterior.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-11-02T00:00:00+00:00'::TIMESTAMPTZ, '410ff477f315c0166ebd38784853fc556ec70b2dfd423c99101ba220d3e9d095'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Trabajos en clase todas las semanas, muchos quices y los proyectos aunque son grandes al dividirse en tantas entregas son llevaderos. Es buen profesor y tiene un método de enseñanza muy sencillo. Todo lo que son revisiones, calificaciones y comunicación es mediante el asistente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-10-19T00:00:00+00:00'::TIMESTAMPTZ, '8ff8984bff4c0163101cf5020c128067c2140a58f4335c8eaf2aa3a58e166006'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'No se aprende nada con ese profesor, y para ayudar, solo el asistente ofrece ayuda y califica absolutamente todo. El profesor lo único que da son las clases donde el 90% son trabajos y quices que son igualmente hechos por el asistente.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'a309b5d28b29a1a52922e57a6442072d117a5bfce1e058739885eb32dc857a6e'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Se pasa facil aun que son proyectos pesados, quizzes todas las semanas de una lectura hasta 80-120pag. La asistente es 10/10 este semestre, eso fue lo unico bueno. El profe es de muy alta edad entonces le cuestan algunas cosas, pero tampoco es justificación para solo dejar trabajos de IA.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'da913ade2006a904e819ef5c0f84c08ef39080865506c3ad6ae7722a17229cd7'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Clases aburridas, muchos quices (9), revisa duro el proyecto (baja por todo), trabajos en clase cada semana, tareas, talleres esos no los revisa duro si cumple con todo, es fácil de pasar pero sus clases son un bostezo'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '0cb06e549c7289c12853dd36974b99ce81137c4f18272e26fb6a70b37f7cebdf'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Esta bien usar IA pero el se abusa ya que no se puede entender las instrucciones de los trabajos en clase claramente. La asistente es la que revisada todo lo demás y es un amor intenta ayudar en lo que puede, siempre esta abierta a sugerencias'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '92439a873efdf74e11dd9ae05681939e55fd5b6cf2eedb36f9b6209c7ddfd227'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El profesor es un descarado que no es capaz de realizar ni los trabajos en clase por el mismo, todos son hechos por Gemini. Proyectos estupidamente grandes. Todas las tareas y proyectos trabajos fueron revisados por la asistente ('::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1c52e671616d51e07968d7a7b91c066e169b1aff07713a98b6954c0dbd92af72'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Profe horrible. Es un vago, con costos da clase, este semestre incluso puso a los estudiantes a darlas la mayoría. No explica nada, con costos dice ahí unos pocos conceptos de presentaciones hechas con chat. Todos los trabajos son hechos por chat, y se ve no se molesta ni en borrar emojis. Mal profe'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-05-04T00:00:00+00:00'::TIMESTAMPTZ, '6ec868c1d7454b2895b341a56281633773c71f954996c4a3f43496cf706c2b7b'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'El profe como tal no es que enseñe mucho, la mayoria son presentaciones hechas por gpt y videos de yt. La materia es muy facil y entendible a pesar de lo anterior dicho. Los proyectos son lo mas complicado pero se logran sacar. Eso si, el asistente a veces es muy quisquilloso y hasta necio'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-08-05T00:00:00+00:00'::TIMESTAMPTZ, 'be34e292d6cae3642ed1921e81d5b6ab256cf332de71d8b824a59f18c75eee79'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Verdaderamente una experiencia miserable. No es bonito esforzarse tanto todos los días sin falta para que se califique un avance como si fuera mediocre. Aun así se puede pasar y bien. El profe es buena gente, es el asistente el que califica bien duro y tiene el control de todo el curso.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd59b546a36777421a028fbaa5530a8ea69dce55c948a10b29d1705e965d609c2'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Facil, como todo con Jaime, el curso en general es un bostezo, lo unico divertido es hacer las progras, que al final unicamente valen un 18% de la nota (Se pueden no mandar y pasar el curso facilmente)'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9f7ba91dfc2099bfb093595edaa7e763c712ee4f0e1d2edb6ff0bdf65f4e364d'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es un curso demasiado facil, como cualquier curso con Jaime, el asistente califica rudo pero al fin y al cabo se termina pasando el curso sin ni siquiera mandar la segunda progra'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-06-10T00:00:00+00:00'::TIMESTAMPTZ, '1cd394bf465b588f11a5fc84f4e2e54da01dc24a245358bba98e30d970656837'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El curso era semipresencial y por la cara decidió hacerlo regular, todas las semanas se hace trabajo evaluado en clase, fáciles, pero en el proyecto el asistente le va a bajar por todo, la documentación la revisa con una lupa, en la progra como no sabe nada si le echa hablada y funcione todo sale ok'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2025-05-30T00:00:00+00:00'::TIMESTAMPTZ, '917a974089ab9cc6f8a8bf042e43958be1c28ed09410c7ba8a99203a472e0cc4'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'La clase es full presencial aunque podría hacerlo asincrónico porque es solo hacer un trabajo muy x, ver videos y un diagrama que él solo lee. Muy de vez en cuando enseña cosas por sí mismo. Alejandro Castro, asistente malparido, para él, es el único que está bien y siempre califica demasiado duro.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-04-09T00:00:00+00:00'::TIMESTAMPTZ, '4be2ba6c455a56004782a9ad3b71bde4e8a85d15b1ae2c2cc471ea80de847b73'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Simple. El profe es un inutil El asistente es un malparido El curso era facil antes por que el asistente era otro inutil, ahora que el asistente es el ser mas miserable del planeta, el curso es horrible. El profe se roba la plata, no hace nada, solo pone youtube y da presentaciones de chatGPT.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-09T00:00:00+00:00'::TIMESTAMPTZ, '51c8bbab4d27d3a5cf116387396663b9b34e62cebdc7271dbd7a09b64b0d69a9'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Se pasa el curso fácilmente sin aprender nada útil. El profesor busca negatividad en todo y tiene preferencias con estudiantes. La materia es obsoleta, y la asistencia es obligatoria aunque solo lee las mismas presentaciones de hace años.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, '435e00aaf6323faea37dd6220b120b8cebd0f7867ded0f94e6ff364fdab07029'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Hay que entregar semanalmente una tarea y un avance del proyecto, es sumamente claro lo que va a evaluar ya que todo es por rúbrica y los exámenes son muy fáciles'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'd3356ad18ad4387fb7faa44e6dae478360bab128a3f15438119259d1feaab0e9'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Si llevó requerimientos con el entonces casi que es reque2.0, deja tareas cada semana pero son fáciles, se hacen tres quices que son medio largos y dos proyectos. Las clases son un poco aburridas'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '4fbd9c4e15dcd1763dfc4ebec1f65a3226c0560adbe50a586ee57e2c1c7b885c'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Evaluación: 40% Trabajos en clase que son grabar audios se 7 minutos resumiendo algún tema al igual que el 20% Tareas y 40% un proyecto con varios entregables de impacto social real que pueda justificar el eje del curso. La asistencia es obligatoria, martes presencial de 1 y jueves virtual.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '54f86966d3d3fbc5b383fc956705865645c54f2221095d4f1519adb8b86e98c7'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'Hay muchas entregas semanales, pero la mayoría son bastante cortas, aunque requieren reunirse al menos una vez por semana con el cliente. Todas las entregas están definidas desde el inicio del semestre y no se califica duro. Solo hay que conectarse a una o dos clases virtuales al inicio del semestre'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '41e3d4b88ea38f092d2b9978fafc2ab960162744307905bcff525a24cf83217d'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Que necio, siempre busca algo malo que decir, intenso y mal vibroso como él solo. Alicia tampoco es la mejor profe, pero para Proyecto si.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'd86f956d66df1ce7f99a9a6415855fbc1eaca7d40f847a9f6e725952e5d45b43'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Un brete semanal corto, tres quices fáciles pero con la longitud de un examen y dos progras (app y web). Es complicado que aprenda algo realmente importante en AP, pero Jaime lo intenta. Se tiene que bretear para pasar, pero se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-09T00:00:00+00:00'::TIMESTAMPTZ, '23c1954347b5b33aefc565d1c6a975b5920e34ffccb7f204903ca085a66d55b6'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'De 2 clases por semana, 1 es teoría y la otra es práctica, la asistencia es obligatoria. Deja avance del proyecto todas las semanas y 3 exámenes. Es fácil que le vaya bien. Sale en semana 15-16 max. El profe a veces es medio enredado con explicar cosas, pero es muy fácil pasar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ffa65f53a3b457ff326fcb894cd75394ca01eb101eafeae8ed6df1b95acaa9c7'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Ojalá fuera el español el que diera las clases, así no me moriría del aburrimiento.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2024-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'af022e2b78e793033483a616501af00960d35716780bb38a7b6897c4860209ac'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Un profe de mierda el profe la primera de la clase de la semana solo se dedica a leer unas apestosas presentaciones, y la segunda clase, solo se trata de hacer un trabajo cotidiano todo asqueroso, donde las indicaciones no son para nada claras, los proyectos son un asco, y no le ayuda con sus dudas'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-05-02T00:00:00+00:00'::TIMESTAMPTZ, '977fa32490900de885d7854c95cf55c107e540f9049fcf600e53dfafebed1ce9'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Deja muchos trabajos semanales, pero son audios, entonces no hay que sacar mucho rato. El proyecto es sencillo, mientras se lo sepa justificar estará contento. Sólo quita puntos si no entrega algo. Eso sí, la asistencia ahora es obligatoria y las clases son aburridas.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2023-11-30T00:00:00+00:00'::TIMESTAMPTZ, '7b3472256b0140d6a9756a238b2dc065aaaaba332912fc7e8e866a9b72b9adcc'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'El profe explica bien. Sus clases pueden resultar pesadas pero siempre está dispuesto a ayudar. La asistencia es obligatoria pero esto se debió a que muchos se ausentaban y solo entregaban los trabajos en el TD. Los proyectos son fáciles y no tienen mucho peso en la nota; se sacan con tiempo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2ffb08c5d0424d80a9fd23d9b759f2d6d0c20b22b71cf52267549d61a675dfff'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Este señor no deberia dar clases. Cualquier clase que lleve con el va a ser la misma materia con las mismas herramientas obsoletas. No tiene absolutamente nada que aportar a la formacion de profesionales, sin conocimiento tecnico alguno. Facil pasar, solo lleve cualquier cosa a revision y entregab'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'df8182bd12a5ef110dd7ae4633ec6be4e98b24381dfbd7f59047a535bc5fc984'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Jaime Solano es muy buen profesor, mucho amor para él. La clase es bastante aburrida ya que son cosas lógicas o que uno podría googlear fácilmente. Los asistentes suelen calificar con el hígado entonces revisar bien la rúbrica. Si pueden matriculen con él.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd630b086eb84b57c9c9e97c67d69ce9021f14c5d778f1e0f21c90fcf9a8ed1e7'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Distribuye muy bien las asignaciones a lo largo del semestre, así que el curso se pasa fácilmente, siempre y cuando haga esos trabajos. Los trabajos en clase casi siempre se pueden terminar en la misma clase, así que las únicas tareas son los trabajos grupales que deja cada semana para el proyecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Pocos exámenes']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '113f4cebd23cf903373bc527cf829610b815e95676ad75d2e55047deab9936e5'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El profe es muy pura vida, tiene mucha vocación y le interesa que uno aprenda. Deja muchos trabajos que se pueden terminar con algo de empeño en la propia clase. Empiece el proyecto con tiempo. El curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c8840539883a445ade851a5e6ffb05b170d54b5fc3eec39f864923cc21e0c50f'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Deja muchas tareas y trabajos en clase. Ademas hay que hacer un proyecto a lo largo del semestre. A pesar de eso, si hace los trabajos bien le pone 100 en todo entonces se pasa facil. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd3fb0457a3eecd43f537ff97154a53ed1b4e57f258133fb464234526bad8519f'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'El curso con Jaime fué ir a clases para ver materia y hacer tareas cortas con dos proyectos en android, prepárese para anotar porque no pasa las presentaciones pero no es nada complicado encontrar todo en internet además que él dice los libros que usa, un curso sencillo pero hay que esforzarce.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1215dd4fbd7106fb5550e2473383be441da2d981b2450dce40c3dc872daac939'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'AP es casi lo mismo que Reque con él. Es un profe muy pura vida y amable, deja un trabajo semanal grupal sencillo basado en el proyecto y un trabajo en clase fácil igual, los quices no son difíciles. Lo más complicado del curso es que hay que programar una app en android y luego en web'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-11-09T00:00:00+00:00'::TIMESTAMPTZ, '2b6732bc46ed83aeb57a548c7ec2a19b3be6800e904f764a4e28e205a638dc0c'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Casi que todos los cursos que da Jaime son el mismo, si llevó administración de proyectos se va a encontrar con una versión más light de eso. Muchas tareas sencillas semanales (audios, ensayos, presentaciones). Pro tip: haga una cuenta de Instagram como proyecto, es lo más sencillo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9f705e5d84d01aa56d3febdd4be40ce9e92d6fbc54aa70934dc892ac01a0a5e7'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'Es un excelente profesor, muy respetuoso y considerado con los estudiantes. Deja muchísimas asignaciones pero son fáciles de realizar si uno se organiza. El curso se pasa muy fácilmente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '881a63f20f205a95bd5b9e8ab4f4d279b8a21964a9979ab242720bb95d49670c'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Deja trabajos semanales y paralelamente se lleva un gran proyecto. No es difícil solo hay que ser organizado y así se tiene una muy buena nota.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7ef86b9fb55d9b159e874f276cfdabd907a9ca4ecad6189df5168fd20fba003f'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Las clases son verlo leer sus presentaciones, debería ser un curso de debate con estudiantes avanzados en la carrera. Deja demasiados trabajos, sencillos pero en cantidad. Además confunde plagio con citar, así que tendrá que hablar paja...'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'efcf21bbe7fbd8f93846ad944b16aadc4edba01b7799abfdecc4bbbea3773969'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'Deja trabajos semanales y paralelamente se lleva un gran proyecto. No es difícil solo hay que ser organizado y así se tiene una muy buena nota.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, '4c3dfe6aec38d6bd45a7bf4cd6bda1c2bb72b973740805acbf4e1ec76c0db69a'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Deja demasiados trabajos para un curso de 2 créditos y es un desorden. Todas las semanas da 1 clase, deja 1 trabajo asincrónico y 1 tarea (audios, ensayos o presentaciones). El grupo elige que hacer de proyecto, elijan algo fácil. Si entrega todo, es casi seguro que pasa con más de 90.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '7643721ca1d4f1894251c9d554c5a9474605814f1b8e68dcfcc5a9120f6460b8'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'Explicaba cómo hacer los entregables del proyecto UN DÍA antes, quitaba puntos por gusto con reglas que nunca explico, las clases son videos de YT y no se le puede preguntar nada o se molesta y te manda a buscar en Google. Da vergüenza que se robe el salario de esa forma.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, '2d4c68995d611063120e98a3d5bf999b5616bde90d62297da55a044ae35f0f71'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Buen profe, solo asistan a todas las clases porque casi siempre va a dejar trabajo en clase para los que se conectaron. Lo demás se pasa fácil entregando todo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '630171122c01a57a4ba5e9d5ad18635df5dd5f4075bfa373b5b8f5bd540bc705'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es buen profesor. Deja muchos trabajos, suelen ser fáciles pero quitan mucho tiempo. Siempre hay que asistir a clases porque deja trabajos en clase, los cuales son tareas en las que solo da un día y, a veces, son bastantes largas. El curso es muy pesado, pero es fácil de pasar si se es organizado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '4e0db135e052bae58106ee10b396d71dde8f1ffd1d0b4e6b82025e5674156ddc'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Deja demasiados trabajos, parece que no se da cuenta que es un curso de 2 créditos, todo es muy confuso sin embargo es un curso fácil de pasar con buena nota. Los proyectos los debe decidir uno entonces se puede hacer muy simple.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-15T00:00:00+00:00'::TIMESTAMPTZ, '10eda2e55a5add32b9096ef80a770dcb926b33e929403a9a9219cb8b4a2b8dd6'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'En clase no explica casi nada, todo dice que "lo tuvieron que haber visto en el curso anterior" o "lo van a ver en el curso siguiente". El asistente revisa todo y quita puntos hasta por existir. Si le preguntas algo te dice que le preguntes al asistente o que busques en Google xD'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-10-11T00:00:00+00:00'::TIMESTAMPTZ, '566eaeeecc917407e3831d195a3dabc43bb743d9bed95f0c0acc15b41b4035ee'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Este profesor no sirve, no explica nada'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-06T00:00:00+00:00'::TIMESTAMPTZ, '094aeef38a60149da6a730c1f679a3728a7bc6352ac81cde1fec0fcc98b36a54'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Explica las varas que se ocupan para el avance del proyecto 1 día antes de la entrega o de plano no lo explica, asigna trabajos en clase que nunca se pueden terminar en tiempo de clase y es irracional la cantidad de trabajo que asigna y muchas veces con un valor insignificante.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-09-30T00:00:00+00:00'::TIMESTAMPTZ, 'cf28f492952bd9469834c1a3ec8d58a32caad54f519635ca97f981220f7d4369'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Demasiado pesado, los proyectos todas las semanas hay que hacer documentos gigantes, el rango de tiempo para las progras son muy cortos y no valen nada respecto a la dificultad que tienen, el asistente baja puntos hasta por respirar,'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-09-25T00:00:00+00:00'::TIMESTAMPTZ, '69bb8694234baf06b5c729d8e291122b30f83487242b1c06accfd37893eca3b3'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'No sabe nada de computación, no sabe programar en ningún lenguaje, no da clases, las instruccciones son muy confusas, nunca revisa los trabajos, en las revisiones de proyecto nunca sabe nada porque no lee los documentos, califica mal (no tiene ninguna rúbrica ni nada)'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-22T00:00:00+00:00'::TIMESTAMPTZ, '542c3586647067c9167bb37de221a7801c4c9db49d4e1c3eebb522040193077a'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Pésimo profesor no domina nada de computación, anticuado, busca como bajar puntos sin sentido, prepárense para frustrarse.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-22T00:00:00+00:00'::TIMESTAMPTZ, '31aeff912bd88f82ca85f8117208ff50595a2896bbe2add15a95a30c84618145'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Era una clase a la semana, la otra clase lo que hacía era dejar trabajos cortos (audios, ensayos). Los proyectos son sencillos si el grupo de estudiantes lo decide, normalmente las revisiones son durante la clase sincrónica. Deja bastantes trabajos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '4165a98403bb29175a172dd9ed55dbf5ac77e6ba026fd491a20c3c3287d5b1c7'::TEXT, ARRAY[1156]::BIGINT[]),
    (321::BIGINT, 'Muchos trabajos pero fácil de sacar buena nota y pasar. Hay que estar conectado en las clases porque muchas veces hace actividades para entregar durante la misma mañana, además de que varias veces se le olvida subir la grabación.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '0c7a8da6d0213f9bd22f3230d32482ca46f68f18f3c6705d2f1ef7dabc972af6'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Importante estar atento a las fechas, con eso se va bien en el curso. Buen profesor un problema es cuando tienes una consulta se vuelve difícil comunicarse con él. Da la impresión de no saber mucho sobre las evaluaciones (tareas,exam) que deja, todo es la Asistente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '941e8c177ac2c687a09e471b29b74f7bc3f0784f45e1d12bc8b55e50aa0856be'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, '* Virtual * Excelente curso. Explica bien, es bastante agradable. Deja dos proyecto en los que se hacen varias entregas (creo que es la naturaleza del curso) que no son para nada difícil. Solo es de estar atento con las fechas. Si necesitan tiempo extra, da unas horas o un par de días'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '06142a76f1b1c3e8f1b88b3a0e25acf12212bf046eeb86fe3213e0e71a77a6e8'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Si ya llevo con Jaime, es como llevar AP por segunda vez, pide los mismo documentos. Sino tendrá que entregar muchísimos documentos todas las semanas. No hay clases, solo reuniones para las entregas y reuniones semanales con el cliente. Curso fácil para culminar la carrera.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '555c4bec97cb18fc3a026025eb8139c6c7b7afdd8dff6c1470dd1bc9b492f30e'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Muy buen profe, explica muy bien y es fácil sacar buena nota. Sea responsable y haga todos los trabajos y le va a ir muy bien. El profe es muy buena persona y comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '656a6d3e076baa80aad2906c3212d47f18bc8b941b0892df623481c9b23720e5'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es un único proyecto para todo el semestre que se divide en varios entregables. El profesor es muy buena nota si se le pide ayuda. Recomendado al 100%.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'c7efd0b402ed64110308516f4e58e5621fd5f3ac76cd0fbdecf33267c765680c'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Deja bastantes tareas pero son sencillas. Se va desarrollando un proyecto durante todo el semestre. El profe explica con mapas mentales y dando ejemplos de vida real. Muy sistemático con las evaluaciones. Desde inicio de semestre se sabe cómo se va a calificar el curso (a diferencia de muchos)'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '47117448fa40a7e436f409a060e7cac69432c2af2e22fdba9daadbc6d3a38139'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Deja muchas tareas, pero son muy fáciles de hacer. Recomendado 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '76e3022e66f79e5b9d7d6f2ac6afa8090c9c9d97469ae26c4ac7085ea66e7e34'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'El mejor profesor para este curso y como persona tambien, se hacen tareas todas las semanas sin falta. Es un curso donde hay que ser ordenado y aveces es muy pesada la carga combinada con otros cursos, pero si se entrega todo pasa con buena nota y aprende bastante del area de proyectos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-25T00:00:00+00:00'::TIMESTAMPTZ, '1bbea1e9c79cdbeb6927087b5a1f7efcee7a54a4527b7b7c7097671a73ea6e0a'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Pide Muchísima documentación. Si uno lo lleva al día se logra todo, pero es de los cursos que más tiempo me ha significado. El código del proyecto lo pide como para semana 12, entonces eso libera un poco el final del semestre. Solo hay que presentarse como a 5 clases presenciales.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '0f6de2d1ed1b68179c86c004cbaf5a131b893ef174795bf43ff317f9f629b53e'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Parece serio al principio pero es súper buena nota. A veces se emociona y deja más tareas aparte de los avances del proyecto semanales. El hecho de hacer 4 exámenes que valen 7.5% c/u ayuda mucho porque la materia no se acumula. Sabe mucho del tema.Lean los libros si quieren salir bien.Recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'adfc14e0d0fc21c14326d536b32aa72484b1f94ce5c77f279485cce2ce7b78a0'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Es buen profesor para el curso. Las clases son un poco aburrida. Si entrega todos los trabajos pasa. Tiene una muy buena organización del tiempo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f1b260d52a938f5cf21bbd1f7af0dcb90ae62ec9b1078d8d191e9a7013c8085e'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Hace el curso bastante pesado porque asigna tareas cada semana sin falta, sin embargo eso hace que ninguna evaluacion valga mucho. Como profe parece serio pero es un vacilon, es bastante estricto con las asistencias. Si se organiza bien y entrega todo lo que pide, pasa con buena nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '87420b211269bd9bf58c5d8c14c247014afbc2316f3b19e2c617688048344d01'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Los proyectos son largos, implican mucha documentación y programación. Hay muchas tareas y cotidianos, la asistencia es importante. Los exámenes no son largos y la mayoría de veces son generales (depende del asistente). Hace algunas clases bastante interactivas. Lo recomiendo :)'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '84014c8421ef31ba7f0303e79673ab9690c99814b29d6f7c2e924f1d83e4e97b'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es bastante bueno. Deja demasiadas tareas, pero son muy sencillas. El profe solo da la clase, todo lo revisa el asistente. Es muy comprensivo y no le molesta correr trabajos ni entregas. Pasa lista todas las clases, por lo que es importante asistir.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a64019cae62902e6f8d11b25b571cc4b3b570271a30c21d5605c5dd44df89122'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'En general es un buen profesor, da la clase teorica y luego la aplica a la practica. TODO lo hace y califica el asistente. Un curso bastante llevadero y 100% pasable con él, nada más hacer todos los trabajos que deje'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dece06a18d80766a3d22a2d16c0e954258c9bd3764964d0b8104e6c6c3672473'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Buen profe, tiene un asistente que ayuda mucho en clases y en examenes, solo hace quices, tareas y trabajo en clase por lo que hace que el curso sea facil de pasar'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ca9e0cc6186aeb311f2875c5f0d7d99082664216fa7921b3a5e7676cdd393e34'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'No hace examenes, solo quices. Es verdad que le cuesta explicar, pero da un ambiente muy cómodo y se preocupa de que los estudiantes aprendan. El asistente es el complemento perfecto y si hace las tareas todo bien.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '793e9e9db4df7a075c8d0fed3d1b9e5d0dc32424c6b2f39b3930124fe9e6984f'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Trata de explicar pero no se le entiende, para él todo el curso es facilísimo. Hace tareas todas las semanas y no hace exámenes sino quices cada dos semanas. El asistente ayuda mucho'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '865fffd2c16b40f46181d7f2d3f72965e8d0c38ec2a3c9a9475de506a11e8538'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Deja miles de trabajos y en los exámenes entran miles de capítulos que no se interesa por enseñar. Es fácil pasar el curso pero no le gusta enseñar.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2018-04-03T00:00:00+00:00'::TIMESTAMPTZ, '8f211afc382ec9dcb52913551ad4a79f764a19a505fcdd1e2f7b92b03160a78a'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Hace examenes cada 2 semanas, son acumulativos, eso es bueno ya que el porcentaje de cada examen es bajo, hay tareas y trabajo en clase todas las semanas. Excelente profesor, se le entiende y se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, '36619a7dfb5b1b4fb3997dae9da020e65793cacd94f2e7e6bd74e8f01aa45242'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Deja muchos trabajos, pero la materia es bastante clara, en realidad es un curso bonito, lo recomiendo para esta materia'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '9a349be16976cb8d1c3dca0b9c80619a9edd6f32f76e0949fbce7f09bca17119'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'No es muy claro al explicar. Deja tarea todas las semanas y los trabajos en clase a veces son un poco volados. En vez de examen hace 7 quices en semestre, al haber tantas evaluaciones las cosas valen menos. El asistente califica suave y le explica todo lo que necesita. El curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd4e9cd23ab0fd206d11f8ba79fa2fecb289f505d8896e3fb2278c6678fc101cf'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Como 5000 trabajos en el curso, pero en grupos de 3 salen rápido. También deja varias tareillas cortas y trabajos en clase, al punto que c/u termina valiendo poco, y puede que haga una exposición. Lo usual son 5 exámenes. Es pura vida y se aprende.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2017-10-27T00:00:00+00:00'::TIMESTAMPTZ, '084f6ee1c97f1576d5c0aa1112b93e37b4c80df408e4158efa9abf7539e96c14'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Si tiene mucho tiempo de sobra meta con este profe, de lo contrario no lo haga porque quita demasiado tiempo. Deja trabajos todas las semanas y en su mayoría largo si se compara con el valor que tienen en la nota del curso.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6a1fd297bf225a7883221c82c768cefbe8fbcc497452c7019d2b8f2a9e6c290f'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Proyectos sencillos pero muy largos, exámenes cada dos semanas, tareas cada semana. En general consume muchísimo tiempo. El profe sabe bastante, clases amenas pero se tornan insoportables después de tanto trabajo. Recomendado si quiere aprender y tiene tiempo extra. PASA LISTA AL INICIO Y FINAL!!!!!'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd6b94768ffebe9d0910ec23f64520ba6ad03317ae87d639d78eb4b97a59b393d'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El asistente hace todo y ayuda demasiado. La evaluación es favorable, hace 6/7 quizes en lugar de examenes y tareas semanales. Clases muy aburridas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8f60f77891c615f3acd445cea6b18e17c1bdbfb4cc33bd38edca59678fac525c'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'El profesor no hace absolutamente nada, el salario deberían dárselo a los asistentes que son los que dan el curso y califican. Aprendí gracias a los tutores y un asistente.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'fd2472a49a7e6ee3e52c9b9ca6154edfab20e2f7cf128d96da05b6f84f605dba'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'El profe es buena nota, solo que no ayuda tanto, o lo intenta pero a uno lo deja igual o peor, pero el curso es pasable con él, además los asistentes ayudan mucho en todo'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-07T00:00:00+00:00'::TIMESTAMPTZ, '225227363e485b42ff736124fe176c112d8ea3739d1a9fbd1703e1c4ae9decd1'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'El profesor no hace nada y tampoco ayuda, todo lo hacen los asistentes que son muy buena nota, no explica nada.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-04-06T00:00:00+00:00'::TIMESTAMPTZ, '6293b622299f16bf5bfb96aabbc9ac342594bb6bd3e920d4bf52e69a98f06b0f'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Si me dieran a elegir entre llevar un curso con Jaime, o una colonoscopia con la punta del zapato de un payaso. Realmente le solicitaría al payaso, que lo haga tan rápido como pueda. Este profesor es como una reliquia, pero sin valor. Ve metodologías casi tan obsoletas, como él. Mejor Nuñez :D'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-22T00:00:00+00:00'::TIMESTAMPTZ, 'acd48d0c5938233c361f99602a2ec7744505fcca4324123a23f4cca7e1160e49'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'El profe es pura vida, diría que demasiado. Si es cierto que deja mucho brete peeero es fácil, excepto cuando implica programar, ahí se vuela un poquito, pero al menos vale "poco". Los exámenes si eran fáciles, al menos para quien le ponía atención al profe en la clase.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'be0a6dab33f967cd55298a90a2716d96e43ebb4a56a4cad1e474136098833f4c'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El profe es muy buena persona y se nota que sabe mucho; pero explicar no tanto. El curso con él es muy pasable, el asistente es muy bueno (ayuda bastante en tareas, exámenes y califica suave).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2017-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'f74dbba2a9113652497e43e0979c9a1bad3500a7f8c79552e535f319469bb7f1'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'la teoria es super aburrida pero si es pasable el curso con el'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '66ef4e401882e7687381012d9dc7b3f00dd0f2f0330a5e75b335c58107ee44a9'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Elementos es un curso que consta de una clase teórica y otra practica. La clase teórica la da el profe y la practica el asistente. El asistente deja muchas tareas lo cual ayuda a practicar para los exámenes y son en parejas.El profe no es malo pero tampoco es el mejor, el asistente es excelente'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-03T00:00:00+00:00'::TIMESTAMPTZ, '6f045ffedcef13fcdf1c1bf322ea882f60df087cfcdb0192c4d9f2031d8988e3'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Lo recomiendo si ya saben algo de programación, pero el profesor no es muy claro en la materia y cada dos semanas hace examenes cortos algunos si eran dificiles, pero la mayoria son regulares.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'd5dcf3152ce26ab136cf371ac401f7eb8bfb542abc47e7052483568fbd807017'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'El curso en sí es fácil. En cuestión de los proyectos, el profesor siempre se encuentra dispuesto a guiarnos sobre como proceder ante situaciones imprevistas. Muy buen profe.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'a66e27c6bcba7e07ee44d87b87396a696e2f77b3cb7650a544c6a7a414ef8a0b'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Buen profe, tiene un buen asistente, siempre ayuda, recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-10-19T00:00:00+00:00'::TIMESTAMPTZ, 'd76337f5a873dbc87a1dbc645c8d39beffbcf9a6f285fae5457bee41eb0330c4'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'El profesor sólo viene a dar las clases y dejar trabajos, lo demás lo hace el asistente. Hay trabajos para cada semana y prácticamente todo es en parejas o grupos. Es fácil pasar si se hace todo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2016-07-18T00:00:00+00:00'::TIMESTAMPTZ, '0b48deff5d6fb168d4511e837d7a8971fcdc140c7bccc11a8e016d101b98ab65'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El asistente prácticamente hace todo: califica exámenes, redacta el proyecto, redacta tareas... El curso es muy exigente pues cada semana hay una entrega (avance de proyecto, ensayo...) y son documentos extensos o para los que hay que investigar bastante. Las clases son aburridas.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'be09bb21ee8dffff2dd85fa9dd8dead5733fca225379b869331a0b1ca6222f38'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '71833057e036a6e1e9975589d728c932af941dce3aa345beb270c79470922657'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'En todo el semestre se tienen solamente como dos semanas libres, todo lo demás es pura entrega de avances y tareas. Por la presión de los trabajos se aprende.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd050a3c4f0ef40faee750382fb7794e307d24da352d50cef805fd3623fb7ed7f'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2016-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4d58d5ac17ff6cd6bd012a5a0815a366f909633a4de25c9624935fbbdf87c725'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Deja MUCHOS trabajos!!! Todas las semanas hay que entregar alguna docu! Pero algo se aprende. Lastima que se enfoca en métodos de administración viejos y tediosos. Es medio vago, el asistente hace todo (revisar proyectos, tareas, exámenes, ...). Como persona cae muy bien, es pura vida!'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'adaa686665e7d2ea7e1e7063dee4e3b58c109d315f1f54451c3632811a18bf0e'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Todas las semanas hay avances (mucha documentación), las clases son exposiciones de los mismos estudiantes. Pero se aprende, y no es muy difícil pasar'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '1c0e4aaa36437ac0d6713c8a8d178d9a393a33424ab8c1a95e43237210ac4f34'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'No explica muy bien'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '9bca41ecff6d62164de290139703587cf72d2345a8035c2867e5902ac3a9bdda'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Si tiene un semestre suave, puede llevarlo, porque no le pesará mucho. Tal vez se aprende a ser más disciplinado haciendo proyectos, pero se enfoca demasiado en documentar, lo cual creo que no es el objetivo (más bien sería de entender cómo proceder ante las situaciones).'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '8dd711ccfa14b554eedc6a64961c05a3ea4c30e1959e2c59a7b50e1b54f2e7de'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Deja tares y/o avances de proyecto por semana y se vuelve un curso pesado por la cantidad de trabajo pero por otro lado es bastante pasable si se hace todo y fácil.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2016-05-06T00:00:00+00:00'::TIMESTAMPTZ, 'a6b8d30d1c71379fc5e870092240916785179f2ee9e664f114fda35c15ea138c'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Todas la evaluaciones las hace el asistente por eso nunca sabe ni de que tratan los proyectos, deja muchos trabajos, mientras uno hagan todas las entregas pasa facil el curso asi este bueno o malo lo que se manda. No se tiene mucha retroalimentacion por parte de el.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '51307620394643c510accda933e67bfbbd42f233dabd6bcbbeb0067d9255f7a5'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Yo llevé AP con él y cambié mi perspectiva. Aprendí mucho y quedé satisfecho. Solamente hay que ponerle y ya. Lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-25T00:00:00+00:00'::TIMESTAMPTZ, '882256c4bfc9356d6a0b253f54d990bb020bab0ee01b31bbc8e8d95ad7469363'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Esta muy des-actualizado con la materia que el esta dando. Dejar 10 libros y decir que la materia es simplemente todo lo que esta en los libros y después explicar solo lo mas trivial de lo trivial en clases es fallar como professor. En palabras simples, es un vago deja que los asistentes hagan TODO.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'bcfa321bc2ffccdc8c2123564a526dec67226610645187abfff787c13c2f797e'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Curso de mucho trabajo y mucho que leer. Examenes cortos y difíciles diseñados para quedar a todos. Un sistema de evualuación sin sentido. La única guía para los proyectos es una plantilla que no sirve para nada. La progra es larga y de mucho trabajo para solo un 5%. La asistente es satanás.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-02T00:00:00+00:00'::TIMESTAMPTZ, '15f06821229d8fc352ac2119ee16c389190f93a32b0e3d89565016fa6bf013d6'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Clases entretenidas, buen profesor, explica en las clases de teoría pero en la practica todo se lo deja al asistente. Quices rudillos, las tareas salvan bastante. Mal asistente.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'c74aaf976e50dbd6f51c3a74843cb1fdfcce6d34a73eb3d646311cad43adda92'::TEXT, ARRAY[1249]::BIGINT[]),
    (321::BIGINT, 'Muy bueno y da ejemplos claros de la teoría. Los quices son algo rudos y los asistentes son algo rudos en calificar. Mucha documentación y siempre una parte programada en los proyectos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'c36826e2517a97c27b5b0a6f0533abbd42584194cd2664a180b7024cc7814a2b'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Las clases entretenidas, es muy pura vida. Casi todo (p/ no decir todo) es el asistente.. pero no es nada del otro mundo. Docus largas al menos p/ el prmer proyecto y en el 2do es casi repetir los mismos.. curso pasable si se hacen las varas y buen profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-08T00:00:00+00:00'::TIMESTAMPTZ, '2804e1f6d3e289947fc403fc9b854a2703b0dfee178c8404fbcbc4463f725f80'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Siempre Dispuesto a atender a sus estudiantes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'c9bf5efef7ec77be15431df741c568a2bbc01227e98cea9786366c3075c09633'::TEXT, ARRAY[1159]::BIGINT[]),
    (321::BIGINT, 'Excelente profesor y demasiado buena gente, todo lo califican los asistentes y a veces son un poco rudos, pero los cursos son pasables :) Super recomendado aunque es un curso pesado con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-28T00:00:00+00:00'::TIMESTAMPTZ, '0409df7211f2ac016cb39a9d88faf670cb1acff216b9096a80c48221bd780dbe'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Explica muy bien, hay que ponerle con los documentos pero no es nada del otro mundo. Hace el primer proyecto con grupos random.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-11T00:00:00+00:00'::TIMESTAMPTZ, 'b202a0274da8d716b7747867906738bc2955538e611b4ce5da9e33c5b7fdaa10'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Es muy buen profe, se aprende bastante. Aprendí bastante de AP y me dio una perspectiva más clara del curso. Hay que ponerle pero es pasable. Recomiendo matricular este curso con él.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-08T00:00:00+00:00'::TIMESTAMPTZ, '50f030420a33a2857d5c0cc73af03d88c884987fede2a9f84efe135202eca428'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es buen profesor, pero muy teórico, a veces hace falta que haga ejemplos y no que solo mande "plantillas" para rellenar. Aplica exámenes cada 3 semanas (mal hechos por la asistente) que son imposibles de pasar. Es demasiada materia, un curso pesado.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-28T00:00:00+00:00'::TIMESTAMPTZ, '255273196cca26be029fed45694b44f3936bf74f66c17c72bb0d1a1e3918f10c'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Llevar este curso con este profesor es ir a aprender materia obsoleta que ya no se usa en la calle. En este curso no debería programarse ya que no ese no es el objetivo. Todo lo revisa el asistente y usualmente las correcciones no son muy claras.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '94f4e7984e7b437f31c142b0764d9343e858473606704999a75d5e2013f53380'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Muy buen curso, se aprende bastante con él. El asistente es muy bueno, pero estricto para calificar. Hay bastante que hacer pero es provechoso.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '20fc760f99bc683efa57cfd2efaf65a5077d5f644c362f0d03bba6e128b55e7c'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Los trabajos no son difíciles pero si son numerosos y muchas veces tediosos, los asistentes califican todo y no es muy confiable la retroalimentación. Las clases pueden ser bastante aburridas. En general se pasa si se hacen los trabajos y se tiene bastante orden en la administración del tiempo!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '717724dd154b472d3f4c26e0cde307a8d408779b700bc0247f665c8c903c170e'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Excelente explicando los temas. Tareas y examenes si son muchos, pero esto ayuda con la nota.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'e5920d5781b622123caeff05d91f3f6ab43875cb23782eef106c61900c8d2492'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es una excelente profesor, muy profesional. Lo único que no me gustó es q ue todo lo califica el asistente...y bueno, no deja de ser un estudiante.. así que la retroalimentación que se recibe es nula o muy dudosa. Hace exposiciones individuales, quices-exámenes todas las semanas...hay que leer mucho'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-23T00:00:00+00:00'::TIMESTAMPTZ, '29bf6f094379630c9f08a4f018da5b57c09526029ac3d52f269fbad69ed9f3ef'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'Excelente profesor y persona, los cursos son fáciles pero hay que hacer muchas tareas y exámenes, el problemas son los asistentes que se busca, sí él calificará todo, todos sacarían 100.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-20T00:00:00+00:00'::TIMESTAMPTZ, '9e373f6249289f4d46a326b34b29644eefeed0dd7553663b8c3bb09b97a7b253'::TEXT, ARRAY[1039, 1052]::BIGINT[]),
    (321::BIGINT, 'Lo recomiendo completamente. Se aprende bastante con todo lo que se hace y se ve en el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, '6f531d4b96faf575705ab782ac1085fd1def2c971a45e8d60bd3cc0289fa29e5'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Se aprende bastante con él y con los trabajos que él y el asistente ponen. AP realmente se vuelve de gran importancia para la carrera.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '9eadcfbf8aac4c1752824c9dd864af032492e5bdcd7d2de390f3bce191c9c986'::TEXT, ARRAY[1052]::BIGINT[]),
    (321::BIGINT, 'Es demasiado bueno. Pero deja trabajos como si no hubiera un mañana. Se aprende demasiado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '8e677263ee0a25b2ba0d1380d37c3b70e78e0a2c64ca045a8d4a97db52759941'::TEXT, ARRAY[1039]::BIGINT[]),
    (321::BIGINT, 'El problema de este profe es que le da todo el trabajo a los asistentes y entre él y los asistentes se encargan de quitarnos todo el tiempo del mundo con sus documentos! es muy bueno puesto que se aprende pero deberia de dejar un poco menos trabajos'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-20T00:00:00+00:00'::TIMESTAMPTZ, '293a908b9d1f2c1990d74b7aa37fe956d71246e86570a26c8fb6677d6edb019e'::TEXT, ARRAY[1039, 1052]::BIGINT[]),
    (321::BIGINT, 'Cae muy bien como persona. Como profesor es aburrido (o tal vez el curso no ayuda) deja muchos trabajos que quitan mucho tiempo. Para requerimientos y AP hay mejores, no sé en otros cursos más interesantes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'fb5e33ae6f403ce49584f7e961d5f984c5e554f2dc96451d1d50929b1de0a383'::TEXT, ARRAY[1039, 1052]::BIGINT[]),
    (321::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '4d10d94164dded6ad129d68333bf93d1677e1d79a70edb9532be589dace97712'::TEXT, ARRAY[1032]::BIGINT[]),
    (321::BIGINT, 'Excelente profesor, deja muchos trabajos pero es muy pasable, casi nadie se queda.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a2582d7ec5d4cc7b6ff0c1ee28feb4ae8ac554236ad42d5e6087545accea4e16'::TEXT, ARRAY[1039]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
